int main(){try{AgencyNpcFixture f;f.common.state().identity.tick=5;const auto offer=f.npc("leader",f.proposal(),PoliticalGovernanceAgencyAuthoredStep::offer);DirectorCatalog catalog;catalog.dynamic_subjects=true;catalog.governance_agency_intents=std::make_shared<const PoliticalGovernanceAgencyIntentCatalog>(f.intents);for(const auto* id:{"leader.policy","delegate.policy","executor.policy"}){DirectorPolicy p;p.organization_id="city";p.templates={DirectorTemplate::governance_agency};p.governance_agency_intent_id="intent";catalog.policies.insert(id,p);}auto rules=f.read();rules.intents=catalog.governance_agency_intents.get();PublicReliefCatalog relief;PublicReliefState relief_state;TaskState tasks;GovernanceTaskState governance_tasks;GovernanceReadContext governance{f.common,*f.cc,f.political_state,f.political,f.governance_state,f.governance,f.state,f.catalog,f.economy,relief,relief_state,tasks,governance_tasks,f.activity};PoliticalGovernanceAgencyBusinessContext business{rules,relief,[](const auto&,const auto&,const auto&){return false;}};DirectorState state;FinitePlan plan;plan.id="plan";plan.subject={SubjectKind::actor,"leader"};plan.policy_id="leader.policy";plan.template_id="governance_agency";plan.phase=PlanPhase::completed;plan.goal_ref=offer;plan.next_review_tick=6;state.archived_plans.insert(plan.id,plan);check(validate_political_governance_agency_intent_director(catalog,state,&business,&governance).ok,"archived own actual offer before original review accepted");state.archived_plans.find("plan")->next_review_tick=5;check(!validate_political_governance_agency_intent_director(catalog,state,&business,&governance).ok,"later actual offer cannot fill older archived review");state.archived_plans.find("plan")->next_review_tick=6;state.archived_plans.find("plan")->subject.id="candidate";check(!validate_political_governance_agency_intent_director(catalog,state,&business,&governance).ok,"principal fact cannot complete delegate intent");state.archived_plans.find("plan")->subject.id="leader";catalog.policies.find("delegate.policy")->governance_agency_intent_id.reset();check(!validate_political_governance_agency_intent_director(catalog,state,&business,&governance).ok,"all three immutable intent policies required");DirectorCatalog old;DirectorState empty;check(validate_political_governance_agency_intent_director(old,empty,nullptr,nullptr).ok,"unselected old profile unchanged");old.policies=catalog.policies;old.dynamic_subjects=true;check(!validate_political_governance_agency_intent_director(old,empty,nullptr,nullptr).ok,"unselected policy cannot silently enable17");std::cout<<checks<<" agency intent source-boundary assertions; source only\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
